"""Build GeoRAG-Bench.

* ``qa.jsonl`` — factual questions generated by the local LLM from sampled paper chunks
  (40 per domain), filtered automatically for answerability.
* ``cross.jsonl`` — questions that need two chunks from different domains that share a
  knowledge-graph entity.
* ``unanswerable.yaml`` — hand-written out-of-scope questions (committed, not generated).
* ``analyze.yaml`` — water-extent tasks whose reference comes from JRC Global Surface Water.

Generation is seeded and resumable: questions already in a file are kept and only the missing
ones are generated.
"""

from __future__ import annotations

import json
import logging
import random
import re
from collections import defaultdict
from pathlib import Path

from pydantic import BaseModel

from georag.agent import prompts
from georag.eval.metrics import content_tokens
from georag.index.graph import KnowledgeGraph
from georag.llm import LLM
from georag.schemas import Chunk

log = logging.getLogger("georag.bench")

PAPER_DOMAINS = ("gis", "remote_sensing", "lidar", "digital_twin", "geo_cv")
_BAD = re.compile(
    r"\b(this|the) (paper|study|work|article|passage|abstract|authors?|proposed|present(ed)? (method|approach))\b|\bwe\b|\bpassage [ab]\b",
    re.I,
)


class GenQA(BaseModel):
    question: str
    answer: str
    answerable: bool = True


def _ok(q: GenQA, passages: list[str], min_support: float = 0.6) -> bool:
    if not q.answerable or len(q.question.split()) < 7 or len(q.answer.split()) < 1:
        return False
    if _BAD.search(q.question) or not q.question.rstrip().endswith("?"):
        return False
    # The answer's content words must come from the source passage(s): no outside knowledge.
    ans = set(content_tokens(q.answer))
    src = set(content_tokens(" ".join(passages)))
    return bool(ans) and len(ans & src) / len(ans) >= min_support


def _read_jsonl(path: Path) -> list[dict]:
    return (
        [json.loads(line) for line in path.read_text().splitlines() if line.strip()] if path.exists() else []
    )


def _append(path: Path, row: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a") as f:
        f.write(json.dumps(row) + "\n")


def build_qa(chunks: list[Chunk], llm: LLM, out: Path, per_domain: int = 40, seed: int = 13) -> list[dict]:
    rows = _read_jsonl(out)
    have: dict[str, int] = defaultdict(int)
    for r in rows:
        have[r["domain"]] += 1
    used = {r["gold"][0] for r in rows}
    rng = random.Random(seed)
    by_domain: dict[str, list[Chunk]] = defaultdict(list)
    for c in chunks:
        if c.domain in PAPER_DOMAINS and len(c.text) > 600:
            by_domain[c.domain].append(c)
    for dom in PAPER_DOMAINS:
        pool = by_domain[dom][:]
        rng.shuffle(pool)
        for c in pool:
            if have[dom] >= per_domain:
                break
            if c.chunk_id in used:
                continue
            try:
                q = llm.json(
                    [
                        {"role": "system", "content": prompts.QA_GEN_SYSTEM},
                        {"role": "user", "content": f"Passage title: {c.title}\n\n{c.text}"},
                    ],
                    GenQA,
                    max_tokens=200,
                )
            except Exception as exc:
                log.warning("generation failed for %s: %s", c.chunk_id, exc)
                continue
            if not _ok(q, [c.text]):
                continue
            row = {
                "id": f"qa-{dom}-{have[dom]:03d}",
                "type": "factual",
                "domain": dom,
                "question": q.question.strip(),
                "answer": q.answer.strip(),
                "gold": [c.chunk_id],
                "gold_docs": [c.doc_id],
            }
            _append(out, row)
            rows.append(row)
            have[dom] += 1
            used.add(c.chunk_id)
            log.info("%s %d/%d  %s", dom, have[dom], per_domain, row["question"])
    return rows


def build_cross(
    chunks: list[Chunk], graph: KnowledgeGraph, llm: LLM, out: Path, n: int = 50, seed: int = 29
) -> list[dict]:
    rows = _read_jsonl(out)
    done_pairs = {tuple(r["gold"]) for r in rows}
    rng = random.Random(seed)
    by_id = {c.chunk_id: c for c in chunks}
    # Entities that are specific enough to bridge two domains: mentioned in 5–150 paper chunks
    # and present in at least two domains.
    bridges = []
    for eid, cids in graph.mentions.items():
        papers = [by_id[c] for c in cids if c in by_id and by_id[c].domain in PAPER_DOMAINS]
        doms = {c.domain for c in papers}
        if 5 <= len(papers) <= 150 and len(doms) >= 2 and graph.g.nodes[eid]["type"] not in ("place",):
            bridges.append((eid, papers))
    rng.shuffle(bridges)
    attempts = 0
    while len(rows) < n and attempts < n * 8 and bridges:
        attempts += 1
        eid, papers = bridges[attempts % len(bridges)]
        a = rng.choice(papers)
        others = [c for c in papers if c.domain != a.domain]
        if not others:
            continue
        b = rng.choice(others)
        key = tuple(sorted((a.chunk_id, b.chunk_id)))
        if key in done_pairs:
            continue
        done_pairs.add(key)
        try:
            q = llm.json(
                [
                    {"role": "system", "content": prompts.CROSS_GEN_SYSTEM},
                    {
                        "role": "user",
                        "content": f"Shared concept: {graph.g.nodes[eid]['label']}\n\nPassage A ({a.title}):\n{a.text}\n\nPassage B ({b.title}):\n{b.text}",
                    },
                ],
                GenQA,
                max_tokens=260,
            )
        except Exception as exc:
            log.warning("cross generation failed: %s", exc)
            continue
        if not _ok(q, [a.text, b.text], min_support=0.5):
            continue
        row = {
            "id": f"cross-{len(rows):03d}",
            "type": "cross",
            "domain": f"{a.domain}+{b.domain}",
            "bridge": eid,
            "question": q.question.strip(),
            "answer": q.answer.strip(),
            "gold": list(key),
            "gold_docs": sorted({a.doc_id, b.doc_id}),
        }
        _append(out, row)
        rows.append(row)
        log.info("cross %d/%d  %s", len(rows), n, row["question"])
    return rows


def load_bench(bench_dir: Path) -> dict[str, list[dict]]:
    import yaml

    unans = yaml.safe_load((bench_dir / "unanswerable.yaml").read_text())
    return {
        "qa": _read_jsonl(bench_dir / "qa.jsonl"),
        "cross": _read_jsonl(bench_dir / "cross.jsonl"),
        "unanswerable": [
            {"id": f"unans-{i:03d}", "type": "unanswerable", "question": q, "gold": []}
            for i, q in enumerate(unans)
        ],
        "analyze": yaml.safe_load((bench_dir / "analyze.yaml").read_text())
        if (bench_dir / "analyze.yaml").exists()
        else [],
    }


class _Para(BaseModel):
    question: str


def build_paraphrased(items: list[dict], llm: LLM, out: Path, max_overlap: float = 0.6) -> list[dict]:
    """Reworded copies of the factual questions, keeping the same gold passages.

    Questions generated from a passage reuse its wording, which flatters lexical retrieval. The
    paraphrased set keeps the information need but limits word overlap with the original question.
    """
    rows = _read_jsonl(out)
    done = {r["source_id"] for r in rows}
    for it in items:
        if it["id"] in done:
            continue
        try:
            p = llm.json(
                [
                    {"role": "system", "content": prompts.PARAPHRASE_SYSTEM},
                    {"role": "user", "content": it["question"]},
                ],
                _Para,
                max_tokens=120,
            )
        except Exception as exc:
            log.warning("paraphrase failed for %s: %s", it["id"], exc)
            continue
        q = p.question.strip()
        a, b = set(content_tokens(it["question"])), set(content_tokens(q))
        overlap = len(a & b) / max(1, len(b))
        if not q.endswith("?") or overlap > max_overlap or len(q.split()) < 5:
            continue
        row = {
            **it,
            "id": f"para-{it['id']}",
            "source_id": it["id"],
            "type": "paraphrased",
            "question": q,
            "overlap": round(overlap, 3),
        }
        _append(out, row)
        rows.append(row)
        log.info("para %d  %s", len(rows), q)
    return rows
